import numpy as np, itertools
S,P=[],[]
for l in open('opt2.xyz').read().strip().split('\n')[2:]:
    t=l.split();S.append(t[0]);P.append([float(x) for x in t[1:4]])
P=np.array(P)
L=[6,26,38,50,62,63]
for i in L: print(i,S[i],round(np.linalg.norm(P[i]-P[0]),3))
for a,b in itertools.combinations(L,2):
    v1=P[a]-P[0];v2=P[b]-P[0]
    ang=np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))
    if ang>150 or ang<70: print("  ",a,b,round(ang,1))
def dih(a,b,c,d):
    b0=P[a]-P[b];b1=P[c]-P[b];b2=P[d]-P[c]; b1/=np.linalg.norm(b1)
    v=b0-np.dot(b0,b1)*b1; w=b2-np.dot(b2,b1)*b1
    return np.degrees(np.arctan2(np.dot(np.cross(b1,v),w),np.dot(v,w)))
print("dih",dih(1,2,3,5))
